var i=`0477-kibbeh`;var o=`world-0477`;var t=`LB`;var a=`western-asia`;var l=4;var r=70;var u={en:`Kibbeh`,ua:`Кіббе`};var g={en:`A traditional dish from Lebanon, centered on bulgur, ground lamb, yellow onion, pine nut. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ліван. Основні складники: булгур, фарш з ягнятини, жовта цибуля, кедровий горіх. Домашній варіант із кількостями продуктів за етапами приготування.`};var s=[{en:`Cook the listed ingredients in simmering water for about 16 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 16 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:16,i:[[`bulgur`,230,`g`],[`water`,300,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`ground-lamb`,480,`g`],[`yellow-onion`,190,`g`],[`pine-nut`,75,`g`],[`ground-cinnamon`,3,`g`],[`allspice-berries`,3,`g`]]},{en:`Shape a thin bulgur-and-meat shell around the cooked pine-nut filling, sealing each kibbeh into a pointed oval.`,ua:`Сформуйте тонку оболонку з булгуру й м’ясної маси навколо обсмаженої начинки з кедровими горіхами; защипніть кіббе у видовжений овал.`,t:[`rolling-out-dough`,`pinching-dumplings`],m:25,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 17 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 17 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:17,i:[[`sunflower-oil`,650,`ml`]]}];var d={slug:i,id:o,country:`LB`,region:a,servings:4,minutes:70,title:u,text:g,steps:s};export{t as country,d as default,o as id,r as minutes,a as region,l as servings,i as slug,s as steps,g as text,u as title};